def calculate_total(price, quantity, discount=0):
    if price < 0 or quantity < 0 or discount < 0:
        raise ValueError("Цена, количество и скидка не могут быть отрицательными")
    if discount > price * quantity:
        raise ValueError("Скидка не может превышать общую стоимость")

    total = price * quantity - discount
    return max(total, 0)  # Итоговая сумма не может быть отрицательной

